문 9. 다음 C 프로그램의 출력 결과는?
#include <stdio.h>
#define SIZE 3
void func(int *m, int *a, int b);
int main(void){
int num[SIZE] = { 1, 3, 6 };
int a=10, b=30;
func(num, &a, b);
printf("a = %d, b = %d\n", a, b);
return 0;
}
void func(int *m, int *x, int y){
int i = 0, n = 0;
y = *x;
n = *(m + 1) + (*m + 2);
*x = ++n;
}

문 19. 다음 Java 프로그램의 출력 결과는?
public class Foo {
public static void main(String[] args) {
int i, j, k;
for (i = 1, j = 1, k = 0; i < 5; i++ ) {
if ((i % 2) == 0)
continue;
k += i * j++;
}
System.out.println(k);
}
}
